import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/utils/date_formatter.dart';import '../../../models/incident.dart';import '../../../providers/incident_provider.dart';import '../../../shared/widgets/loading_indicator.dart';import '../widgets/incident_status_badge.dart';class IncidentDetailsScreen extends StatelessWidget{const IncidentDetailsScreen({super.key,required this.incidentId});final String incidentId;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Incident details')),body:FutureBuilder<Incident?>(future:context.read<IncidentProvider>().getById(incidentId),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const LoadingIndicator();if(s.hasError||s.data==null)return const Center(child:Text('Incident could not be loaded.'));final i=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[Text(i.title,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:10),IncidentStatusBadge(status:i.status),ListTile(title:const Text('Category'),subtitle:Text(i.category)),ListTile(title:const Text('Location'),subtitle:Text(i.location)),ListTile(title:const Text('Reported by'),subtitle:Text(i.reporterName)),ListTile(title:const Text('Submitted'),subtitle:Text(DateFormatter.format(i.createdAt))),const Divider(),Text(i.description),for(final url in i.photoUrls)Padding(padding:const EdgeInsets.only(top:12),child:Image.network(url))]);}));}}
